class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent daily strategies with separately tracked share lots."""

    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Indicators are updated manually so every rule uses today's completed bar.
        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        # Keep private lots aligned with split-adjusted brokerage holdings.
        if data.Splits.ContainsKey(self.spy) and self.spy_lot:
            self.spy_lot = int(round(self.spy_lot / data.Splits[self.spy].SplitFactor))
        if data.Splits.ContainsKey(self.aapl) and self.aapl_lot:
            self.aapl_lot = int(
                round(self.aapl_lot / data.Splits[self.aapl].SplitFactor)
            )

        bars = data.Bars
        spy_bar = bars[self.spy] if bars.ContainsKey(self.spy) else None
        aapl_bar = bars[self.aapl] if bars.ContainsKey(self.aapl) else None

        # Market-state quantities continue to advance whenever their data exists.
        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(bars.ContainsKey(symbol) for symbol in self.symbols)
        if all_bars_present:
            self._evaluate_spy(spy_bar)
            self._evaluate_aapl(aapl_bar)

        # These are prior-day values on the next daily invocation, even when a
        # different subscribed ticker made today's rule evaluation ineligible.
        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value
        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def _evaluate_spy(self, bar: TradeBar):
        if not self.spy_sma.IsReady or self.previous_spy_sma is None:
            return

        close = bar.Close
        sma = self.spy_sma.Current.Value
        crosses_below = (
            self.previous_spy_close >= self.previous_spy_sma and close < sma
        )
        crosses_above = (
            self.previous_spy_close <= self.previous_spy_sma and close > sma
        )

        # Sells are evaluated before buys.
        if self.spy_lot and crosses_below:
            self.MarketOrder(self.spy, -self.spy_lot, tag="Strategy A sell")
            self.spy_lot = 0

        if not self.spy_lot and crosses_above:
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity, tag="Strategy A buy")
                self.spy_lot = quantity

    def _evaluate_aapl(self, bar: TradeBar):
        if not self.aapl_rsi.IsReady:
            return

        # Sells are evaluated before buys, allowing the now-empty lot's buy
        # condition to be considered on the same bar.
        if self.aapl_lot and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.aapl_lot, tag="Strategy B sell")
            self.aapl_lot = 0

        if not self.aapl_lot and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if self.Portfolio.Cash >= cash_to_invest:
                quantity = int(cash_to_invest // bar.Close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity, tag="Strategy B buy")
                    self.aapl_lot = quantity

