class IndependentSpyAndAppleStrategies(QCAlgorithm):
    """Two independent, daily strategies with separately tracked security lots."""

    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            security = self.add_equity(ticker, Resolution.DAILY)
            self.symbols[ticker] = security.symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.pending_symbols = set()

        # One extra bar makes both sides of an SMA crossing available.
        self.set_warm_up(self.SMA_PERIOD + 1, Resolution.DAILY)

    def on_data(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = data.bars[spy] if data.bars.contains_key(spy) else None
        aapl_bar = data.bars[aapl] if data.bars.contains_key(aapl) else None

        current_spy_sma = None
        if spy_bar is not None:
            self.spy_closes.append(Decimal(spy_bar.close))
            if len(self.spy_closes) == self.SMA_PERIOD:
                current_spy_sma = sum(self.spy_closes) / Decimal(self.SMA_PERIOD)

        if aapl_bar is not None:
            aapl_close = Decimal(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        all_bars_present = all(
            data.bars.contains_key(symbol) for symbol in self.symbols.values()
        )

        if all_bars_present and not self.is_warming_up:
            # Sells are evaluated before buys.
            self._evaluate_spy_sell(spy_bar, current_spy_sma)
            self._evaluate_aapl_sell()
            self._evaluate_spy_buy(spy_bar, current_spy_sma)
            self._evaluate_aapl_buy(aapl_bar)

        # Preserve each day's close/average pair for exact next-day crossings,
        # even when another subscribed ticker was missing on this Slice.
        if spy_bar is not None and current_spy_sma is not None:
            self.previous_spy_close = Decimal(spy_bar.close)
            self.previous_spy_sma = current_spy_sma

    def _evaluate_spy_sell(self, bar, sma):
        symbol = self.symbols["SPY"]
        if not self._lot_is_open(symbol) or symbol in self.pending_symbols:
            return
        if not self._spy_values_ready(sma):
            return

        close = Decimal(bar.close)
        crossed_below = (
            self.previous_spy_close >= self.previous_spy_sma and close < sma
        )
        if crossed_below:
            self._submit_lot_order(symbol, -self.portfolio[symbol].quantity, "A sell")

    def _evaluate_aapl_sell(self):
        symbol = self.symbols["AAPL"]
        if not self._lot_is_open(symbol) or symbol in self.pending_symbols:
            return
        if self.aapl_rsi.is_ready and self.aapl_rsi.current.value > Decimal(60):
            self._submit_lot_order(
                symbol, -self.portfolio[symbol].quantity, "B sell"
            )

    def _evaluate_spy_buy(self, bar, sma):
        symbol = self.symbols["SPY"]
        if self._lot_is_open(symbol) or symbol in self.pending_symbols:
            return
        if not self._spy_values_ready(sma):
            return

        close = Decimal(bar.close)
        crossed_above = (
            self.previous_spy_close <= self.previous_spy_sma and close > sma
        )
        if crossed_above:
            quantity = self.calculate_order_quantity(symbol, 0.40)
            if quantity > 0:
                self._submit_lot_order(symbol, quantity, "A buy")

    def _evaluate_aapl_buy(self, bar):
        symbol = self.symbols["AAPL"]
        if self._lot_is_open(symbol) or symbol in self.pending_symbols:
            return
        if not self.aapl_rsi.is_ready or self.aapl_red_streak < 3:
            return

        cash_to_invest = Decimal(20_000)
        if self.portfolio.cash < cash_to_invest:
            return
        quantity = int(math.floor(cash_to_invest / Decimal(bar.close)))
        if quantity > 0:
            self._submit_lot_order(symbol, quantity, "B buy")

    def _spy_values_ready(self, current_sma):
        return (
            current_sma is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        )

    def _lot_is_open(self, symbol):
        return self.portfolio[symbol].quantity > 0

    def _submit_lot_order(self, symbol, quantity, tag):
        ticket = self.market_order(symbol, quantity, False, tag)
        if ticket is not None:
            self.pending_symbols.add(symbol)

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID,
        ):
            self.pending_symbols.discard(order_event.symbol)

