class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    AAPL_RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.AAPL_RSI_PERIOD, MovingAverageType.Wilders
        )

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_pending = False
        self.aapl_pending = False

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
        else:
            spy_bar = None

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            if (
                self.aapl_previous_close is not None
                and aapl_bar.Close < self.aapl_previous_close
            ):
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
        else:
            aapl_bar = None

        have_every_bar = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if have_every_bar:
            self._evaluate_spy(spy_bar)
            self._evaluate_aapl(aapl_bar)

        if spy_bar is not None and self.spy_sma.IsReady:
            self.spy_previous_close = spy_bar.Close
            self.spy_previous_sma = self.spy_sma.Current.Value
        if aapl_bar is not None:
            self.aapl_previous_close = aapl_bar.Close

    def _evaluate_spy(self, bar):
        if (
            not self.spy_sma.IsReady
            or self.spy_previous_close is None
            or self.spy_previous_sma is None
            or self.spy_pending
        ):
            return

        close = bar.Close
        sma = self.spy_sma.Current.Value
        crosses_above = (
            self.spy_previous_close <= self.spy_previous_sma and close > sma
        )
        crosses_below = (
            self.spy_previous_close >= self.spy_previous_sma and close < sma
        )

        if self.spy_lot > 0:
            if crosses_below:
                self.spy_pending = True
                self.MarketOnOpenOrder(
                    self.symbols["SPY"], -self.spy_lot, "Strategy A sell"
                )
        elif crosses_above:
            quantity = floor(0.40 * self.Portfolio.TotalPortfolioValue / close)
            if quantity > 0:
                self.spy_pending = True
                self.MarketOnOpenOrder(
                    self.symbols["SPY"], quantity, "Strategy A buy"
                )

    def _evaluate_aapl(self, bar):
        if not self.aapl_rsi.IsReady or self.aapl_pending:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.aapl_pending = True
                self.MarketOnOpenOrder(
                    self.symbols["AAPL"], -self.aapl_lot, "Strategy B sell"
                )
        elif self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = floor(20_000 / bar.Close)
            if quantity > 0:
                self.aapl_pending = True
                self.MarketOnOpenOrder(
                    self.symbols["AAPL"], quantity, "Strategy B buy"
                )

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order.Symbol == self.symbols["SPY"]:
            if order_event.Status == OrderStatus.Filled:
                self.spy_lot = max(0, self.spy_lot + int(order_event.FillQuantity))
            self.spy_pending = False
        elif order.Symbol == self.symbols["AAPL"]:
            if order_event.Status == OrderStatus.Filled:
                self.aapl_lot = max(0, self.aapl_lot + int(order_event.FillQuantity))
            self.aapl_pending = False

