                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close >= self.previous_spy_sma
                and spy_bar.close < self.spy_sma.current.value
            )
            if crossed_below:
                self.strategy_a_order_pending = True
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)

        if self.strategy_b_shares > 0 and not self.strategy_b_order_pending:
            if self.aapl_rsi.current.value > 60:
                self.strategy_b_order_pending = True
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)

    def _evaluate_buys(self, spy_bar, aapl_bar):
        if self.strategy_a_shares == 0 and not self.strategy_a_order_pending:
            crossed_above = (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_bar.close > self.spy_sma.current.value
            )
            if crossed_above:
                quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self.strategy_a_order_pending = True
                    self.market_order(self.symbols["SPY"], quantity)

        if self.strategy_b_shares == 0 and not self.strategy_b_order_pending:
            if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
                quantity = int(20_000 // aapl_bar.close)
                if quantity > 0:
                    self.strategy_b_order_pending = True
                    self.market_order(self.symbols["AAPL"], quantity)

    def on_order_event(self, order_event: OrderEvent):
        symbol = order_event.symbol
        if order_event.status in (OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED):
            if symbol == self.symbols["SPY"]:
                self.strategy_a_shares += order_event.fill_quantity
            elif symbol == self.symbols["AAPL"]:
                self.strategy_b_shares += order_event.fill_quantity

        if order_event.status in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID,
        ):
            if symbol == self.symbols["SPY"]:
                self.strategy_a_shares = max(0, self.strategy_a_shares)
                self.strategy_a_order_pending = False
            elif symbol == self.symbols["AAPL"]:
                self.strategy_b_shares = max(0, self.strategy_b_shares)
                self.strategy_b_order_pending = False

